import{_ as a,o,c as r,a0 as c}from"./chunks/framework.BZ80FTt7.js";const u=JSON.parse('{"title":"2026-07-09：学习视觉组内容","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-07-09-vision-group.md","filePath":"blog/2026-07-09-vision-group.md"}'),d={name:"blog/2026-07-09-vision-group.md"};function t(l,e,i,s,n,p){return o(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="_2026-07-09-学习视觉组内容" tabindex="-1">2026-07-09：学习视觉组内容 <a class="header-anchor" href="#_2026-07-09-学习视觉组内容" aria-label="Permalink to &quot;2026-07-09：学习视觉组内容&quot;">​</a></h1><p>今天看了小学期自学指南里的视觉组内容。它没有直接从识别算法开始，而是先要求补基础工程能力、C++ 代码阅读能力和 ROS 2 基础概念。</p><p>这个安排挺合理。视觉组最后做的是机器人感知和决策链路里的输入端，但真正开始之前，先要能打开工程、读懂代码、理解报错，再知道数据在 ROS 2 里怎么流动。</p><h2 id="视觉组先学什么" tabindex="-1">视觉组先学什么 <a class="header-anchor" href="#视觉组先学什么" aria-label="Permalink to &quot;视觉组先学什么&quot;">​</a></h2><p>以前我容易把视觉组理解成“写 OpenCV 或深度学习代码”。今天看完之后，感觉这个理解有点跳步。</p><p>在真实项目里，视觉代码不是单独跑一个脚本就结束。它通常在一个工程里运行，要读取相机或 rosbag 数据，处理图像，发布识别结果，再和电控、导航或上层策略连接起来。这里面任何一环出问题，都需要基础工程能力来定位。</p><p>所以视觉组前期最重要的不是马上追求效果，而是先能进入项目。</p><h2 id="今天抓住的几个点" tabindex="-1">今天抓住的几个点 <a class="header-anchor" href="#今天抓住的几个点" aria-label="Permalink to &quot;今天抓住的几个点&quot;">​</a></h2><h3 id="基础工程能力" tabindex="-1">基础工程能力 <a class="header-anchor" href="#基础工程能力" aria-label="Permalink to &quot;基础工程能力&quot;">​</a></h3><p>视觉组要求掌握基本 Linux 命令、Git 命令和 VSCode 工程浏览能力。</p><p>这些看起来不像“视觉知识”，但它们决定了我能不能独立看项目。比如进入目录、搜索文件、查看修改、读终端报错，这些动作以后每天都会用。如果连报错信息都描述不清，后面问问题也很难问到点上。</p><p>今天先把几个命令记下来：<code>cd</code>、<code>ls</code>、<code>mkdir</code>、<code>cp</code>、<code>rm</code>、<code>grep</code>，以及 <code>clone</code>、<code>pull</code>、<code>status</code>、<code>diff</code>。后面要真正用起来，而不是只背名字。</p><h3 id="c-基础" tabindex="-1">C++ 基础 <a class="header-anchor" href="#c-基础" aria-label="Permalink to &quot;C++ 基础&quot;">​</a></h3><p>指南里没有要求系统学完整套 C++，重点是能读项目代码。</p><p>这对我很关键。视觉项目里会遇到函数、<code>if</code>、<code>for</code>、<code>struct</code>、<code>class</code>、<code>std::vector</code>、<code>std::string</code>、引用、指针、<code>.hpp</code> 和 <code>.cpp</code> 的关系，还有 <code>namespace</code>。这些不一定都要一次学透，但至少看到代码时不能完全卡住。</p><p>后面学 C++ 时，我要把目标放在“读懂工程里的代码”，而不是陷进语法细节里出不来。</p><h3 id="ros-2-基础概念" tabindex="-1">ROS 2 基础概念 <a class="header-anchor" href="#ros-2-基础概念" aria-label="Permalink to &quot;ROS 2 基础概念&quot;">​</a></h3><p>ROS 2 是视觉结果接入机器人系统的重要部分。</p><p>今天先记住几个核心概念：Node 是执行具体功能的程序单元，Topic 是节点之间传数据的通道，Message 是传输的数据格式，Launch 用来启动多个节点，rosbag 用来录制和回放机器人数据。</p><p>这些概念还比较抽象，但已经能看出一条链路：视觉节点处理图像，通过 Topic 发布 Message，其他节点订阅结果并继续控制机器人。等后面看真实工程时，要把代码和这条链路对上。</p><h2 id="对视觉组的新理解" tabindex="-1">对视觉组的新理解 <a class="header-anchor" href="#对视觉组的新理解" aria-label="Permalink to &quot;对视觉组的新理解&quot;">​</a></h2><p>今天最大的收获是，视觉组不是只学算法。</p><p>算法当然重要，但工程能力决定了算法能不能跑在真实机器人上。能不能复现环境、能不能读懂代码、能不能描述报错、能不能用 rosbag 回放数据，这些都会影响后面的调试效率。</p><p>如果只是会写一个单文件 demo，离战队项目还有距离。视觉组真正要做的是把感知结果稳定地接进整车系统。</p><h2 id="资料入口" tabindex="-1">资料入口 <a class="header-anchor" href="#资料入口" aria-label="Permalink to &quot;资料入口&quot;">​</a></h2><ul><li><a href="https://learngitbranching.js.org/?locale=zh_CN" target="_blank" rel="noreferrer">Learn Git Branching</a></li><li><a href="https://www.learncpp.com/" target="_blank" rel="noreferrer">LearnCpp</a></li><li><a href="https://docs.ros.org/en/humble/Tutorials.html" target="_blank" rel="noreferrer">ROS 2 Humble 官方教程</a></li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>[ ] 用 Git 交互式教程练习 <code>clone</code>、<code>pull</code>、<code>status</code>、<code>diff</code> 对应的概念</li><li>[ ] 复习 C++ 里的 <code>struct</code>、<code>class</code>、引用和指针</li><li>[ ] 看 ROS 2 里的 Node、Topic、Message 入门教程</li><li>[ ] 找一个小工程，用 VSCode 练习搜索文件和跳转定义</li></ul><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>今天对视觉组的理解变得更实际了：先补工程基础，再谈识别算法，最后把结果接进机器人系统。</p>',30)])])}const b=a(d,[["render",t]]);export{u as __pageData,b as default};
